				{ title = "The ritual pieces", tip = "Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy), 6 Large Brilliant Shards (Enchanting), 25 Dark Iron Ore (Mining, in Blackrock Depths and the Searing Gorge) and 35 Black Dragonscales (Skinning, black dragonkin of the Burning Steppes). Make or gather what your professions allow; buy the rest at the Auction House.", zone = 1428, goals = {
					{ kind = "collect", quest = 7626, objective = 1, item = 9264, count = 10, note = "Elixir of Shadow Power" },
					{ kind = "collect", quest = 7627, objective = 1, item = 14344, count = 6, note = "Large Brilliant Shard" },
					{ kind = "collect", quest = 7627, objective = 2, item = 11370, count = 25, note = "Dark Iron Ore" },
					{ kind = "collect", quest = 7628, objective = 1, item = 15416, count = 35, note = "Black Dragonscale" },
				} },
