					{ kind = "accept", quest = 7624 },
				} },
				{ title = "Ulathek the Traitor", tip = "Ulathek waits in a side chamber by a bridge on the way back up. Speak to him and he and his four guards attack; none are elite. Take his heart back to Lord Banehollow, drinking another potion if the first wore off.", zone = 1448, goals = {
					{ kind = "kill", npc = 14523, optional = true, note = "Ulathek" },
