					{ kind = "accept", quest = 7625 },
				} },
				{ title = "Xorothian Stardust", tip = "Ur'dan, beside Lord Banehollow, sells the Xorothian Stardust; he only deals with you while a Shadowy Potion is active. Bring plenty of gold.", zone = 1448, goals = {
					{ kind = "buy", npc = 14522, item = 18687, note = "Xorothian Stardust, from Ur'dan" },
