		{
			id = "forever/legacy/legacy-challenges", title = "Legacy Challenges", category = "Legacy", levels = { 1, 60 }, zone = 1428, version = 1,
			steps = {
				{ title = "Classes: level 25", tip = "Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself.", zone = 1428, goals = {
					{ kind = "level", level = 25 },
				} },
				{ title = "Classes: level 45", tip = "Level 45 with this character's class.", zone = 1428, goals = {
					{ kind = "level", level = 45 },
				} },
				{ title = "Classes: level 60", tip = "Level 60 with this character's class.", zone = 1428, goals = {
					{ kind = "level", level = 60 },
				} },
				{ title = "Tradeskills: Alchemy", tip = "Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"Alchemy 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System.", zone = 1428, goals = {
					{ kind = "skill", profession = "Alchemy", value = 150 },
					{ kind = "skill", profession = "Alchemy", value = 225 },
					{ kind = "skill", profession = "Alchemy", value = 300 },
				} },
				{ title = "Tradeskills: Blacksmithing", tip = "Follow the Polestar guide \"Blacksmithing 1-300\" (Professions).", zone = 1428, goals = {
					{ kind = "skill", profession = "Blacksmithing", value = 150 },
					{ kind = "skill", profession = "Blacksmithing", value = 225 },
					{ kind = "skill", profession = "Blacksmithing", value = 300 },
				} },
				{ title = "Tradeskills: Enchanting", tip = "Follow the Polestar guide \"Enchanting 1-300\" (Professions).", zone = 1428, goals = {
					{ kind = "skill", profession = "Enchanting", value = 150 },
					{ kind = "skill", profession = "Enchanting", value = 225 },
					{ kind = "skill", profession = "Enchanting", value = 300 },
				} },
				{ title = "Tradeskills: Engineering", tip = "Follow the Polestar guide \"Engineering 1-300\" (Professions).", zone = 1428, goals = {
					{ kind = "skill", profession = "Engineering", value = 150 },
					{ kind = "skill", profession = "Engineering", value = 225 },
					{ kind = "skill", profession = "Engineering", value = 300 },
				} },
				{ title = "Tradeskills: Leatherworking", tip = "Follow the Polestar guide \"Leatherworking 1-300\" (Professions).", zone = 1428, goals = {
					{ kind = "skill", profession = "Leatherworking", value = 150 },
					{ kind = "skill", profession = "Leatherworking", value = 225 },
					{ kind = "skill", profession = "Leatherworking", value = 300 },
				} },
				{ title = "Tradeskills: Tailoring", tip = "Follow the Polestar guide \"Tailoring 1-300\" (Professions).", zone = 1428, goals = {
					{ kind = "skill", profession = "Tailoring", value = 150 },
					{ kind = "skill", profession = "Tailoring", value = 225 },
					{ kind = "skill", profession = "Tailoring", value = 300 },
				} },
				{ title = "PvP: battleground reputations (Alliance)", tip = "Exalted with each battleground faction is worth a point (4 in all; this page shows three, see the note). Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation and Alterac Valley Reputation. The Diplomat Legacy perk increases reputation gains.", only = { factions = { "Alliance" } }, zone = 1428, goals = {
					{ kind = "rep", factionId = 890, standing = "Exalted", note = "Warsong Gulch" },
					{ kind = "rep", factionId = 509, standing = "Exalted", note = "Arathi Basin" },
					{ kind = "rep", factionId = 730, standing = "Exalted", note = "Alterac Valley" },
					{ kind = "note", text = "Blizzard counts four battleground reputations, but our faction data has three per side (Warsong Gulch, Arathi Basin, Alterac Valley). The fourth is likely tied to Forever's new PvP content; check the in-game Legacy panel." },
				} },
				{ title = "PvP: battleground reputations (Horde)", tip = "Exalted with each battleground faction is worth a point (4 in all; this page shows three, see the note). Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation and Alterac Valley Reputation. The Diplomat Legacy perk increases reputation gains.", only = { factions = { "Horde" } }, zone = 1428, goals = {
					{ kind = "rep", factionId = 889, standing = "Exalted", note = "Warsong Gulch" },
					{ kind = "rep", factionId = 510, standing = "Exalted", note = "Arathi Basin" },
					{ kind = "rep", factionId = 729, standing = "Exalted", note = "Alterac Valley" },
					{ kind = "note", text = "Blizzard counts four battleground reputations, but our faction data has three per side (Warsong Gulch, Arathi Basin, Alterac Valley). The fourth is likely tied to Forever's new PvP content; check the in-game Legacy panel." },
				} },
				{ title = "PvP: honor ranks", tip = "Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing.", zone = 1428, goals = {
					{ kind = "kill", name = "enemy players for honor until PvP Rank 3" },
					{ kind = "kill", name = "enemy players for honor until PvP Rank 7" },
					{ kind = "kill", name = "enemy players for honor until PvP Rank 10" },
					{ kind = "kill", name = "enemy players for honor until PvP Rank 13" },
					{ kind = "kill", name = "enemy players for honor until PvP Rank 14" },
				} },
				{ title = "PvP: Field of Honor", tip = "The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself.", zone = 1428, goals = {
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 4 journey quest" },
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 7 journey quest" },
					{ kind = "kill", name = "enemy players and finish the Field of Honor week 10 journey quest" },
				} },
				{ title = "Adventure: explore the world map", tip = "Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character.", zone = 1428, goals = {
					{ kind = "note", text = "Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it." },
					{ kind = "note", text = "This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded." },
				} },
				{ title = "Adventure: Lord Valthalak", tip = "The Lord Valthalak questline is a point. It is the level 60 dungeon-set chain: Deliana (Ironforge) or Mokvar (Orgrimmar) send you through In Search of Anthion and Anthion's Parting Words to Bodley at Blackrock Mountain, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and Mea Culpa, Lord Valthalak end with Return to Bodley. Back to the Beginning then leads to the class Saving the Best for Last quests.", zone = 1428, goals = {
					{ kind = "accept", quest = 8996, map = 1428, x = 32.2, y = 25.8, optional = true, note = "Spirit of Lord Valthalak, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to Bodley's Blackrock Mountain)" },
					{ kind = "turnin", quest = 8996, optional = true, note = "Bodley: Return to Bodley" },
					{ kind = "accept", quest = 8997, optional = true, only = { factions = { "Alliance" } }, note = "Bodley offers it once Return to Bodley is turned in" },
					{ kind = "accept", quest = 8998, optional = true, only = { factions = { "Horde" } }, note = "Bodley offers it once Return to Bodley is turned in" },
					{ kind = "note", text = "Which quest Blizzard counts as the end of the questline (Return to Bodley or your class's Saving the Best for Last) is unconfirmed until the Legacy data is recorded." },
				} },
				{ title = "Adventure: Back to the Beginning (Alliance)", tip = "Deliana then offers your class's Saving the Best for Last, the final upgrade of the dungeon set.", only = { factions = { "Alliance" } }, zone = 1455, goals = {
					{ kind = "turnin", quest = 8997, optional = true, note = "Deliana, Ironforge" },
				} },
				{ title = "Adventure: Back to the Beginning (Horde)", tip = "Mokvar then offers your class's Saving the Best for Last, the final upgrade of the dungeon set.", only = { factions = { "Horde" } }, zone = 1454, goals = {
					{ kind = "turnin", quest = 8998, optional = true, note = "Mokvar, Orgrimmar" },
				} },
				{ title = "Dungeons: level 15-25", tip = "The final boss of every level 15-25 dungeon earns one point together. Tick each boss off when you kill it; the grouping follows the usual Classic level ranges, so check the in-game Legacy panel for the exact list.", zone = 1454, goals = {
					{ kind = "kill", npc = 11520, note = "Ragefire Chasm" },
