		{
			id = "forever/reputation/argent-dawn", title = "Argent Dawn Reputation", category = "Reputation", levels = { 50, 60 }, zone = 1422, version = 1,
			steps = {
				{ title = "Argent Dawn Commission (Alliance)", tip = "The Argent Dawn starts out Neutral. Take the Commission from Argent Officer Pureheart at Chillwind Camp and wear it: in Classic, Scourgestones only drop while the Argent Dawn Commission trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains.", only = { factions = { "Alliance" } }, zone = 1422, goals = {
					{ kind = "accept", quest = 5401 },
					{ kind = "turnin", quest = 5401 },
				} },
				{ title = "Argent Dawn Commission (Horde)", tip = "The Argent Dawn starts out Neutral. Take the Commission from Argent Officer Garush at The Bulwark and wear it: in Classic, Scourgestones only drop while the Argent Dawn Commission trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains.", only = { factions = { "Horde" } }, zone = 1420, goals = {
					{ kind = "accept", quest = 5405 },
					{ kind = "turnin", quest = 5405 },
				} },
				{ title = "Minion's Scourgestones to Friendly", tip = "Ghouls and skeletons all over Western Plaguelands drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at Chillwind Camp, Garush at The Bulwark, Duke Nicholas Zverenhoff at Light's Hope Chapel). Each turn-in also pays an Argent Dawn Valor Token for the Argent quartermasters.", zone = 1422, goals = {
					{ kind = "collect", item = 12840, count = 20, map = 1422, x = 41.8, y = 70.4, optional = true },
					{ kind = "talk", npc = 10840, optional = true, only = { factions = { "Alliance" } }, note = "Argent Officer Pureheart, Chillwind Camp" },
					{ kind = "talk", npc = 10839, optional = true, only = { factions = { "Horde" } }, note = "Argent Officer Garush, The Bulwark" },
					{ kind = "rep", factionId = 529, standing = "Friendly" },
				} },
				{ title = "Invader's Scourgestones to Honored", tip = "Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and Runecloth. Hand Invader's in 10 at a time and Minion's 20 at a time to Duke Nicholas Zverenhoff at Light's Hope Chapel. In Classic both stop giving reputation at Honored.", zone = 1423, goals = {
					{ kind = "collect", item = 12841, count = 10, map = 1423, x = 40, y = 51.3, optional = true },
					{ kind = "talk", npc = 11039, optional = true, note = "Duke Nicholas Zverenhoff, Light's Hope Chapel" },
					{ kind = "rep", factionId = 529, standing = "Honored" },
				} },
				{ title = "Corruptor's Scourgestones and dungeons to Revered", tip = "From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in Stratholme and Scholomance carry the reputation. Corruptor's stones drop from the Scourge bosses there (Darkmaster Gandling, Marduk Blackpool, Vectus) and from Araj the Summoner and Putridius in Western Plaguelands. Many dungeon runs pay off faster than any open-world farm.", zone = 1423, goals = {
					{ kind = "note", text = "Run Stratholme (both wings) and Scholomance, killing every Scourge you pass." },
					{ kind = "talk", npc = 11039, optional = true, note = "Duke Nicholas Zverenhoff, Light's Hope Chapel" },
					{ kind = "rep", factionId = 529, standing = "Revered" },
				} },
				{ title = "Argent Dawn to Exalted", tip = "Keep running Stratholme and Scholomance and turning in every Corruptor's Scourgestone at Light's Hope Chapel until Exalted.", zone = 1423, goals = {
					{ kind = "talk", npc = 11039, optional = true },
					{ kind = "rep", factionId = 529, standing = "Exalted" },
				} },
			},
		},
		{
