				{ title = "Back to Burninate", zone = 1427, goals = {
					{ kind = "turnin", quest = 7722 },
				} },
				{ title = "Fiery Flux supplies to Friendly", tip = "Restoring Fiery Flux Supplies repeats in three versions: Kingsblood, Iron Bars or Heavy Leather, each with Coal and an Incendosaur Scale. Incendosaurs (level 47-49) in the north of Searing Gorge drop a scale every time; Burninate himself sells Coal.", zone = 1427, goals = {
					{ kind = "collect", item = 18944, map = 1427, x = 44.6, y = 24.9, optional = true },
					{ kind = "talk", npc = 14624, optional = true, note = "Master Smith Burninate: Restoring Fiery Flux Supplies" },
					{ kind = "rep", factionId = 59, standing = "Friendly" },
				} },
				{ title = "Lokhtos Darkbargainer to Honored", tip = "Lokhtos Darkbargainer trades in the Grim Guzzler inside Blackrock Depths. His Favor Amongst the Brotherhood turn-ins take Dark Iron Ore (mined from Dark Iron Deposits with Mining), Blood of the Mountain, Fiery Core, Lava Core and Core Leather. Lothos Riftwaker at the Blackrock Mountain entrance offers attunement to the Molten Core.", zone = 1427, goals = {
					{ kind = "goto", label = "Blackrock Mountain", map = 1427, x = 32.1, y = 94.7 },
					{ kind = "note", text = "Dark Iron Ore: Favor Amongst the Brotherhood, Dark Iron Ore at Lokhtos, repeatable." },
					{ kind = "rep", factionId = 59, standing = "Honored" },
				} },
				{ title = "Thorium Brotherhood to Revered", tip = "The Molten Core materials carry the rest: Fiery Cores drop from Firewalkers, Flameguards and Firelords, and Lava Cores from Lava Elementals, Lava Reavers and Molten Destroyers there. Blood of the Mountain comes from Molten Destroyers and rarely elsewhere.", zone = 1427, goals = {
					{ kind = "note", text = "Molten Core materials: Favor Amongst the Brotherhood, Fiery Core, Lava Core, Core Leather and Blood of the Mountain, all repeatable at Lokhtos." },
